candidates.raw:
size_t i;
int config_ok;
int input_ok;
adcs_vec3_t axes[4];
double power[4];
double torque[4];
double scale;
double req_mot = 0.0, req_reg = 0.0;
double slew_limit;
double net_req, net_del = 0.0;
double del_mot = 0.0, del_reg = 0.0;
int any_limit = 0;
unint32 power_mask = 0U, slew_mask = 0U;
adcs_vec3_t h;
adcs_vec3_t req_torque = {0, 0, 0}, del_torque = {0, 0, 0};
adcs_vec3_t unit_axis, term;

config_ok = (wp_config.release_filtered_w >= 0.0) &&
            (wp_config.release_filtered_w < wp_config.trip_filtered_w) &&
            (wp_config.filter_alpha >= 0.0) && (wp_config.filter_alpha <= 1.0) &&
            (wp_config.motoring_limit_w > 0.0) &&
            (wp_config.regenerative_limit_w > 0.0) &&
            (wp_config.max_torque_slew_nm_per_cycle > 0.0) &&
            (wp_config.release_cycles >= 1U) && (wp_config.release_cycles <= 20U);

if (wp_input.enable == 0 && config_ok) {
    wp_state.mode = WP_NORMAL;
    wp_state.clean = 0U;
    wp_state.filtered_abs_power_w = 0.0;
    for (i = 0; i < 4U; i++)
        wp_state.previous_torque_nm[i] = 0.0;
    wp_output.mode = WP_NORMAL;
    wp_output.clean = 0U;
    wp_output.power_limited_mask = 0U;
    wp_output.slew_limited_mask = 0U;
    wp_output.requested_net_power_w = 0.0;
    wp_output.delivered_net_power_w = 0.0;
    wp_output.requested_motoring_power_w = 0.0;
    wp_output.requested_regenerative_power_w = 0.0;
    wp_output.delivered_motoring_power_w = 0.0;
    wp_output.delivered_regenerative_power_w = 0.0;
    wp_output.filtered_abs_power_w = 0.0;
    wp_output.momentum_norm_nms = 0.0;
    wp_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wp_output.requested_body_torque_nm = (adcs_vec3_t){0, 0, 0};
    wp_output.delivered_body_torque_nm = (adcs_vec3_t){0, 0, 0};
    for (i = 0; i < 4U; i++)
        wp_output.limited_torque_nm[i] = 0.0;
    return;
}

input_ok = config_ok && (wp_input.wheels != NULL) &&
           (wp_input.torque_nm != NULL) && (wp_input.wheel_count == 4U);

if (input_ok) {
    for (i = 0; i < 4U; i++) {
        if (adcs_vec3_normalize(&wp_input.wheels[i].axis_body, ADCS_EPS_NORM,
                                &axes[i]) != ADCS_OK) {
            input_ok = 0;
            break;
        }
        if ((!isfinite(wp_input.torque_nm[i])) ||
            (!isfinite(wp_input.wheels[i].speed_rad_s))) {
            input_ok = 0;
            break;
        }
    }
}

if (!input_ok) {
    wp_output.mode = WP_FAULT;
    wp_output.clean = 0U;
    wp_output.power_limited_mask = 0U;
    wp_output.slew_limited_mask = 0U;
    wp_output.requested_net_power_w = 0.0;
    wp_output.delivered_net_power_w = 0.0;
    wp_output.requested_motoring_power_w = 0.0;
    wp_output.requested_regenerative_power_w = 0.0;
    wp_output.delivered_motoring_power_w = 0.0;
    wp_output.delivered_regenerative_power_w = 0.0;
    wp_output.filtered_abs_power_w = 0.0;
    wp_output.momentum_norm_nms = 0.0;
    wp_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wp_output.requested_body_torque_nm = (adcs_vec3_t){0, 0, 0};
    wp_output.delivered_body_torque_nm = (adcs_vec3_t){0, 0, 0};
    for (i = 0; i < 4U; i++)
        wp_output.limited_torque_nm[i] = 0.0;
    return;
}

h = (adcs_vec3_t){0, 0, 0};
(void)adcs_wheel_momentum(wp_input.wheels, wp_input.wheel_count, &h);
wp_output.momentum_nms = h;
wp_output.momentum_norm_nms = adcs_vec3_norm(&h);

req_mot = 0.0;
req_reg = 0.0;
req_torque = (adcs_vec3_t){0, 0, 0};
for (i = 0; i < 4U; i++) {
    torque[i] = wp_input.torque_nm[i];
    power[i] = torque[i] * wp_input.wheels[i].speed_rad_s;
    if (power[i] > 0.0)
        req_mot += power[i];
    else if (power[i] < 0.0)
        req_reg += -power[i];
    unit_axis = axes[i];
    term = adcs_vec3_scale(&unit_axis, torque[i]);
    req_torque = adcs_vec3_add(&req_torque, &term);
}

for (i = 0; i < 4U; i++) {
    if (power[i] > 0.0) {
        scale = (req_mot > wp_config.motoring_limit_w) ?
                (wp_config.motoring_limit_w / req_mot) : 1.0;
    } else if (power[i] < 0.0) {
        scale = (req_reg > wp_config.regenerative_limit_w) ?
                (wp_config.regenerative_limit_w / req_reg) : 1.0;
    } else {
        scale = 1.0;
    }
    torque[i] = wp_input.torque_nm[i] * scale;
    if (scale < 1.0)
        power_mask |= (unint32)(1U << i);
}

slew_limit = wp_config.max_torque_slew_nm_per_cycle;
for (i = 0; i < 4U; i++) {
    double delta = torque[i] - wp_state.previous_torque_nm[i];
    if (delta > slew_limit) {
        torque[i] = wp_state.previous_torque_nm[i] + slew_limit;
        slew_mask |= (unint32)(1U << i);
    } else if (delta < -slew_limit) {
        torque[i] = wp_state.previous_torque_nm[i] - slew_limit;
        slew_mask |= (unint32)(1U << i);
    }
}

del_mot = 0.0;
del_reg = 0.0;
del_torque = (adcs_vec3_t){0, 0, 0};
for (i = 0; i < 4U; i++) {
    double p = torque[i] * wp_input.wheels[i].speed_rad_s;
    if (p > 0.0)
        del_mot += p;
    else if (p < 0.0)
        del_reg += -p;
    unit_axis = axes[i];
    term = adcs_vec3_scale(&unit_axis, torque[i]);
    del_torque = adcs_vec3_add(&del_torque, &term);
    wp_output.limited_torque_nm[i] = torque[i];
}

net_req = req_mot - req_reg;
net_del = del_mot - del_reg;

wp_output.requested_motoring_power_w = req_mot;
wp_output.requested_regenerative_power_w = req_reg;
wp_output.delivered_motoring_power_w = del_mot;
wp_output.delivered_regenerative_power_w = del_reg;
wp_output.requested_net_power_w = net_req;
wp_output.delivered_net_power_w = net_del;
wp_output.power_limited_mask = power_mask;
wp_output.slew_limited_mask = slew_mask;
wp_output.requested_body_torque_nm = adcs_vec3_scale(&req_torque, -1.0);
wp_output.delivered_body_torque_nm = adcs_vec3_scale(&del_torque, -1.0);

wp_state.filtered_abs_power_w = wp_config.filter_alpha * fabs(net_req) +
                                (1.0 - wp_config.filter_alpha) *
                                    wp_state.filtered_abs_power_w;
wp_output.filtered_abs_power_w = wp_state.filtered_abs_power_w;

any_limit = (power_mask != 0U) || (slew_mask != 0U) ||
            (wp_state.filtered_abs_power_w >= wp_config.trip_filtered_w);

if (any_limit) {
    wp_state.mode = WP_LIMITED;
    wp_state.clean = 0U;
} else {
    switch (wp_state.mode) {
        case WP_LIMITED:
            if (wp_state.filtered_abs_power_w <= wp_config.release_filtered_w) {
                wp_state.mode = WP_RECOVERING;
                wp_state.clean = 1U;
            }
            break;
        case WP_RECOVERING:
            if (wp_state.filtered_abs_power_w <= wp_config.release_filtered_w) {
                wp_state.clean++;
                if (wp_state.clean >= wp_config.release_cycles) {
                    wp_state.mode = WP_NORMAL;
                    wp_state.clean = 0U;
                }
            } else {
                wp_state.clean = 0U;
            }
            break;
        case WP_NORMAL:
        default:
            wp_state.clean = 0U;
            break;
    }
}

wp_output.mode = wp_state.mode;
wp_output.clean = wp_state.clean;

for (i = 0; i < 4U; i++)
    wp_state.previous_torque_nm[i] = wp_output.limited_torque_nm[i];

