for (i = 0U; i < 4U; i++) {
    mech[i] = wp_input.torque_nm[i] * wl[i].speed_rad_s;
    if (mech[i] > 0.0) req_pos += mech[i];
    else if (mech[i] < 0.0) req_neg += -mech[i];
