lim_mot = (req_pos > wp_config.motoring_limit_w && req_pos > 0.0)
              ? (wp_config.motoring_limit_w / req_pos) : 1.0;
lim_reg = (req_neg > wp_config.regenerative_limit_w && req_neg > 0.0)
              ? (wp_config.regenerative_limit_w / req_neg) : 1.0;

