for (i = 0U; i < 4U; i++) {
    double tq = wp_input.torque_nm[i];
    double scaled;
    if (tq > 0.0) {
        scaled = tq * lim_mot;
        if (lim_mot < 1.0) power_mask |= (1U << i);
    } else if (tq < 0.0) {
        scaled = tq * lim_reg;
        if (lim_reg < 1.0) power_mask |= (1U << i);
    } else {
        scaled = 0.0;
    }
    {
        double prev = wp_state.previous_torque_nm[i];
        double d = scaled - prev;
        if (d > wp_config.max_torque_slew_nm_per_cycle) {
            d = wp_config.max_torque_slew_nm_per_cycle;
            slew_mask |= (1U << i);
        } else if (d < -wp_config.max_torque_slew_nm_per_cycle) {
            d = -wp_config.max_torque_slew_nm_per_cycle;
            slew_mask |= (1U << i);
        }
        limited[i] = prev + d;
    }
}

/* delivered 功率 */
for (i = 0U; i < 4U; i++) {
    double dm = limited[i] * wl[i].speed_rad_s;
    if (dm > 0.0) del_pos += dm;
    else if (dm < 0.0) del_neg += -dm;
}

/* 滤波 */
