if (wp_state.mode == WP_FAULT) {
    /* 保持 FAULT */
} else if (any_limit) {
    wp_state.mode = WP_LIMITED;
    clean_next = 0U;
} else if (wp_state.mode == WP_LIMITED) {
    if (filt_next <= wp_config.release_filtered_w) {
        wp_state.mode = WP_RECOVERING;
        clean_next = 1U;
    } else {
        wp_state.mode = WP_LIMITED;
        clean_next = 0U;
    }
} else if (wp_state.mode == WP_RECOVERING) {
    if (filt_next <= wp_config.release_filtered_w) {
        clean_next = wp_state.clean + 1U;
        if (clean_next >= wp_config.release_cycles) {
            wp_state.mode = WP_NORMAL;
            clean_next = 0U;
        } else {
            wp_state.mode = WP_RECOVERING;
        }
    } else {
        wp_state.mode = WP_LIMITED;
        clean_next = 0U;
    }
} else if (wp_state.mode == WP_NORMAL) {
    if (filt_next > wp_config.release_filtered_w) {
        wp_state.mode = WP_LIMITED;
    } else {
        wp_state.mode = WP_NORMAL;
    }
    clean_next = 0U;
} else {
    /* 无条件兜底分支：覆盖任何未显式枚举的 mode 值 */
    wp_state.mode = WP_LIMITED;
    clean_next = 0U;
