del_torque = (adcs_vec3_t){0, 0, 0};
for (i = 0U; i < 4U; i++) {
    (void)adcs_vec3_normalize(&wl[i].axis_body, ADCS_EPS_NORM, &axis_i);
    term = adcs_vec3_scale(&axis_i, wp_input.torque_nm[i]);
