    term = adcs_vec3_scale(&axis_i, limited[i]);
    del_torque = adcs_vec3_add(&del_torque, &term);
}
req_torque = adcs_vec3_scale(&req_torque, -1.0);
del_torque = adcs_vec3_scale(&del_torque, -1.0);

/* 输出 */
wp_output.mode = wp_state.mode;
wp_output.clean = wp_state.clean;
wp_output.power_limited_mask = power_mask;
wp_output.slew_limited_mask = slew_mask;
wp_output.requested_net_power_w = net_req;
wp_output.delivered_net_power_w = del_pos - del_neg;
wp_output.requested_motoring_power_w = req_pos;
wp_output.requested_regenerative_power_w = req_neg;
wp_output.delivered_motoring_power_w = del_pos;
wp_output.delivered_regenerative_power_w = del_neg;
wp_output.filtered_abs_power_w = wp_state.filtered_abs_power_w;
wp_output.momentum_norm_nms = adcs_vec3_norm(&momentum);
wp_output.momentum_nms = momentum;
wp_output.requested_body_torque_nm = req_torque;
wp_output.delivered_body_torque_nm = del_torque;
for (i = 0U; i < 4U; i++) wp_output.limited_torque_nm[i] = limited[i];

