slew_active = (slew_mask != 0U) ? 1 : 0;

alpha = wp_config.filter_alpha;
prev_filt = wp_state.filtered_abs_power_w;
abs_net = fabs(net_req);
wp_state.filtered_abs_power_w = alpha * abs_net + (1.0 - alpha) * prev_filt;
