wp_output.mode = new_mode;
wp_output.clean = (new_mode == WP_RECOVERING) ? wp_state.clean : 0U;
wp_output.power_limited_mask = power_mask;
wp_output.slew_limited_mask = slew_mask;
for (i = 0; i < 4; i++)
    wp_output.limited_torque_nm[i] = limited[i];
if (motoring_mask == 0U && regen_mask == 0U) {
    /* both masks empty: no directional contributors, still consistent */
}

